    intro=heading('WIEDZA / '+('WARSZTAT' if workshop else 'PERSPEKTYWY'), 'Z wiedzy<br><em>zrób użytek.</em>' if workshop else 'Zanim zrobisz ruch,<br><em>zobacz więcej.</em>', 'Małe zadanie, jasna kolejność i rezultat do sprawdzenia.' if workshop else 'O stronach, komunikacji i technologii przez pryzmat decyzji, które podejmujesz w swojej firmie.')
    title='Nowe zapytanie prosto na telefon.' if workshop else 'Po co małej firmie agent AI?'
    url='/warsztat/pierwsza-automatyzacja.html' if workshop else '/blog/po-co-agent-malej-firmie.html'
    graphic='''<div class="editorial-process" aria-hidden="true" data-editorial-motion><span>01 / NOWE ZAPYTANIE</span><p>„Porozmawiajmy<br>o projekcie.”</p><i>↓</i><span>02 / PRZYGOTOWANE INFORMACJE</span><p>Wiesz, kto pisze.<br>Wiesz, czego potrzebuje.</p><i>↓</i><span>03 / TWÓJ NASTĘPNY KROK</span><p class="editorial-result">Możesz <em>odpowiedzieć.</em></p></div>'''
    return intro+f'''<section class="studio-section pad-top-zero"><div class="container">{h['editorial_nav'](workshop)}<article class="editorial-feature"><a class="editorial-visual" href="{url}" aria-label="Przeczytaj: {title}">{graphic}<span class="image-action" aria-hidden="true">↗</span></a><div class="editorial-feature-copy"><p class="eyebrow">{('PIERWSZY PROCES / INSTRUKCJA' if workshop else 'AUTOMATYZACJA / PERSPEKTYWA')}</p><h2>{title}</h2><p>{('Zaplanuj drogę od formularza do powiadomienia. Sprawdź dane, odbiorcę i sytuacje wyjątkowe.' if workshop else 'Jak rozpoznać proces, który warto usprawnić? I kiedy wystarczy prosta automatyzacja?')}</p>{link('Otwórz materiał',url,True)}<span class="editorial-note">Prosto. Z konkretnym zastosowaniem.</span></div></article></div></section>'''+closing('Automatyzacja',description='Masz podobny problem w swojej firmie? Opisz, co dziś robisz ręcznie.')

