def apply_studio(pages, h):
    replacements={
      'index.html':home_content(), 'oferta.html':offer_content(h),
      'strony-www.html':web_content(h), 'marketing.html':marketing_content(h),
      'social-media.html':marketing_content(h,True), 'realizacje.html':projects_content(h),
      'o-donie.html':approach_content(), 'automatyzacja.html':automation_content(h),
      'akademia.html':academy_content(), 'blog.html':journal_content(h),
      'warsztat.html':journal_content(h,True)
    }
    for path,marker in [('strony-www.html','<section class="build-scene"'),('marketing.html','<section class="campaign-scene'),('social-media.html','<section class="campaign-scene')]:
        replacements[path]=replacements[path][replacements[path].index(marker):]
    academy=replacements['akademia.html']
    academy=academy[academy.index('<section class="prompt-lab'):]
    academy=academy.replace('<p class="eyebrow">SPRÓBUJ NA PROSTYM PRZYKŁADZIE.</p><h2>Lepsze pytanie.<br><em>Lepszy początek.</em></h2>', '<p class="eyebrow">AKADEMIA AI / SPRÓBUJ, A ZROZUMIESZ.</p><h1>Z „nie wiem jak”<br><em>w „potrafię”.</em></h1>')
    academy=academy.replace('<div class="prompt-options"', contact('Zapytaj o program','Akademia AI')+'<div class="prompt-options"')
    replacements['akademia.html']=academy
    for path,body in replacements.items():
        title,desc,_,cls=pages[path]
        pages[path]=(title,desc,body,cls)
    for path in ['kontakt.html','wycena.html']:
        title,desc,body,cls=pages[path]
        start=body.index('<section class="section pad-top-zero">')
        body=body[start:]
        # Keep the renovation choice distinct so service links prefill the right intent.
        needle='<span>Nowa marka</span></label>'
        body=body.replace(needle, needle+'<label class="choice"><input type="radio" name="usluga" value="Odnowa marki"><span>Odnowa marki</span></label>')
        new_heading=heading('KONTAKT / ZACZNIJMY OD ROZMOWY' if path=='kontakt.html' else 'ZAPYTANIE O WYCENĘ / TRZY KRÓTKIE KROKI', 'Co ma się<br><em>zmienić?</em>' if path=='kontakt.html' else 'Nadajmy pomysłowi<br><em>konkretny kształt.</em>', 'Opowiedz o swojej firmie. Wystarczą dwa zdania o tym, gdzie jesteś i dokąd chcesz dojść.',link('Zadzwoń: +48 573 569 141','tel:+48573569141',True))
        pages[path]=(title,desc,new_heading+body,cls)
    for path in ['blog/po-co-agent-malej-firmie.html','warsztat/pierwsza-automatyzacja.html']:
        title,desc,body,cls=pages[path]
        body=body.split('<section class="big-close">')[0]+closing('Automatyzacja')
        pages[path]=(title,desc,body,cls)
    _,_,home,cls=pages['index.html']
    pages['index.html']=('Probatum — daj się zapamiętać. Strony, marki i marketing.','Budujemy marki od zera, istniejącym dajemy nową siłę. Strategia, strony internetowe, marketing i automatyzacje Probatum.',home,cls)
    pages['horyzont.html']=('Horyzont — koncepcyjny projekt strony | Probatum','Interaktywny przykład strony architektonicznej i spójnej komunikacji. Projekt koncepcyjny Probatum.',concept_content(),'concept')
